#!/usr/bin/env python3
"""Print the pinned tokenizer regex's Unicode letter and number tables."""

from itertools import groupby

from tokenizers import Regex, __version__, normalizers


def main():
    if __version__ != "0.21.1":
        raise RuntimeError("use tokenizers 0.21.1 from the Llama 3.2 reference lock")
    scalars = "".join(chr(cp) for cp in range(0x110000) if not 0xD800 <= cp < 0xE000)
    print("// Code generated by testdata/generate_llama32_unicode.py. DO NOT EDIT.")
    print("\npackage tokenizer")
    for name, category in [("Letters", "L"), ("Numbers", "N")]:
        remove_other = normalizers.Replace(Regex(r"[^\p{" + category + r"}]+"), "")
        members = map(ord, remove_other.normalize_str(scalars))
        print(f"\nvar llama3{name} = []llama3RuneRange{{")
        # In a contiguous run, each code point and its index increase together.
        for _, run in groupby(enumerate(members), lambda pair: pair[1] - pair[0]):
            points = [point for _, point in run]
            print(f"\t{{0x{points[0]:04X}, 0x{points[-1]:04X}}},")
        print("}")


if __name__ == "__main__":
    main()
